import {getOperationsContext} from './operations.mjs';
const view=document.getElementById('operationsView'),lang=()=>window.voltguard.language;
const labels={en:{enter:'Frontline view',exit:'Full workspace',inspect:'Inspect measured 3D',voice:'Read general guidance',export:'Export this report',call:'Actual emergency: call 999',note:'Historical record. No connected vehicle or active fire is established.'},zh:{enter:'前線簡潔模式',exit:'完整工作台',inspect:'查看實測 3D',voice:'朗讀一般指引',export:'匯出此報告',call:'實際緊急事故：致電 999',note:'歷史記錄；並未確認已連接車輛或發生火警。'}};
const toggle=document.createElement('button');toggle.id='fieldToggle';toggle.type='button';toggle.className='ops-button';toggle.setAttribute('aria-pressed','false');view.querySelector('.operations-intro').append(toggle);
const globalToggle=document.createElement('button');globalToggle.id='globalFieldToggle';globalToggle.type='button';globalToggle.className='masthead-field';globalToggle.setAttribute('aria-controls','operationsView');document.querySelector('.mast-actions').prepend(globalToggle);
const toolbar=document.createElement('div');toolbar.className='field-toolbar';toolbar.hidden=true;toolbar.innerHTML='<p id="fieldNote"></p><div><button id="fieldInspect" type="button" class="ops-button"></button><button id="fieldVoice" type="button" class="ops-button"></button><button id="fieldExport" type="button" class="ops-button"></button><a id="fieldCall" class="ops-button" href="tel:999"></a><button id="fieldExit" type="button" class="ops-button"></button></div>';
view.querySelector('.ops-layout').after(toolbar);
function render(){const c=labels[lang()],enabled=view.classList.contains('field-mode'),ctx=getOperationsContext();toggle.textContent=c[enabled?'exit':'enter'];toggle.setAttribute('aria-pressed',String(enabled));toolbar.hidden=!enabled;for(const[id,key]of[['fieldInspect','inspect'],['fieldVoice','voice'],['fieldExport','export'],['fieldCall','call'],['fieldExit','exit']])document.getElementById(id).textContent=c[key];document.getElementById('fieldNote').textContent=ctx.report?.record.mode==='historical'?c.note:'';document.getElementById('fieldInspect').disabled=document.getElementById('opsInspect').disabled;document.getElementById('fieldExport').disabled=!ctx.report;document.getElementById('fieldVoice').disabled=!('speechSynthesis'in window);}
function syncGlobal(){const active=view.classList.contains('field-mode')&&!view.hidden;globalToggle.textContent=labels[lang()][active?'exit':'enter'];globalToggle.setAttribute('aria-pressed',String(active));}
function setMode(enabled){view.classList.toggle('field-mode',enabled);render();syncGlobal();}
globalToggle.addEventListener('click',()=>{const active=view.classList.contains('field-mode')&&!view.hidden;document.getElementById('operationsTab').click();setMode(!active);document.getElementById(active?'fieldToggle':'fieldInspect').focus();});
toggle.addEventListener('click',()=>setMode(!view.classList.contains('field-mode')));document.getElementById('fieldExit').addEventListener('click',()=>{setMode(false);toggle.focus();});
for(const[field,original]of[['fieldInspect','opsInspect'],['fieldExport','opsJson'],['fieldVoice','opsSpeak']])document.getElementById(field).addEventListener('click',()=>document.getElementById(original).click());
window.addEventListener('voltguard-review-context',render);window.addEventListener('voltguard-language',render);render();
window.addEventListener('voltguard-review-context',syncGlobal);window.addEventListener('voltguard-language',syncGlobal);window.addEventListener('voltguard-view',()=>queueMicrotask(syncGlobal));syncGlobal();
